#include <stdio.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);

    char grid[n][n];
    // Initialize grid with spaces
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            grid[i][j] = ' ';

    int top = 0, bottom = n - 1;
    int left = 0, right = n - 1;

    while (top <= bottom && left <= right) {
        // Move up on left column
        for (int i = bottom; i >= top; i--)
            grid[i][left] = '#';
        left++;

        if (left > right) break;

        // Move right on top row
        for (int j = left; j <= right; j++)
            grid[top][j] = '#';
        top++;

        if (top > bottom) break;

        // Move down on right column
        for (int i = top; i <= bottom; i++)
            grid[i][right] = '#';
        right--;

        if (left > right) break;

        // Move left on bottom row
        for (int j = right; j >= left; j--)
            grid[bottom][j] = '#';
        bottom--;
    }

    // Print result
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            putchar(grid[i][j]);
            if (j < n - 1) putchar(' ');
        }
        putchar('\n');
    }

    return 0;
}

#include <stdio.h>

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        int size = 2 * n - 1;
        // grid[i][j]: i=0 is top row
        char grid[200][200];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                int dist = i;
                if (j < dist) dist = j;
                if (size - 1 - i < dist) dist = size - 1 - i;
                if (size - 1 - j < dist) dist = size - 1 - j;
                if (dist % 2 == 0)
                    grid[i][j] = '#';
                else
                    grid[i][j] = ' ';
            }
        }
        // Print: row 0 is top, but pattern starts from bottom-left
        // So we print from bottom to top? Let's print row size-1 first
        for (int i = size - 1; i >= 0; i--) {
            for (int j = 0; j < size; j++) {
                printf("%c", grid[i][j]);
            }
            printf("\n");
        }
        printf("\n");
    }
    return 0;
}

