int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char **a = (char **)malloc(n * sizeof(char *));
    for (int i = 0; i < n; i++) {
        a[i] = (char *)malloc((n + 1) * sizeof(char));
        for (int j = 0; j < n; j++) a[i][j] = ' ';
        a[i][n] = '\0';
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;

    while (left <= right && top <= bottom) {
        for (int i = bottom; i >= top; i--) a[i][left] = '#';
        left += 2;
        if (left > right) break;

        for (int j = left - 1; j <= right; j++) a[top][j] = '#';
        top += 2;
        if (top > bottom) break;

        for (int i = top - 1; i <= bottom; i++) a[i][right] = '#';
        right -= 2;
        if (left > right) break;

        for (int j = right + 1; j >= left; j--) a[bottom][j] = '#';
        bottom -= 2;
    }

    for (int i = 0; i < n; i++) {
        puts(a[i]);
        free(a[i]);
    }
    free(a);

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<vector<char>> grid(n, vector<char>(n, ' '));

    int dir = 0; // 0: up, 1: right, 2: down, 3: left
    int r = n - 1, c = 0;
    int step = n - 1;

    if (n == 1) {
        grid[0][0] = '#';
    } else {
        while (step > 0) {
            for (int i = 0; i < step; i++) {
                grid[r][c] = '#';
                if (dir == 0) r--;
                else if (dir == 1) c++;
                else if (dir == 2) r++;
                else if (dir == 3) c--;
            }
            dir = (dir + 1) % 4;
            if (dir % 2 == 0) step -= 2;
            if (step <= 0) break;
            // move one extra step in new direction if needed
            for (int i = 0; i < step; i++) {
                grid[r][c] = '#';
                if (dir == 0) r--;
                else if (dir == 1) c++;
                else if (dir == 2) r++;
                else if (dir == 3) c--;
            }
            dir = (dir + 1) % 4;
            if (dir % 2 == 0) step -= 2;
        }
        // ensure center if n odd
        if (n % 2 == 1) {
            grid[n/2][n/2] = '#';
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cout << grid[i][j];
            if (j < n - 1) cout << ' ';
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<vector<char>> grid(n, vector<char>(n, ' '));

        // Directions: up, right, down, left
        int dr[] = {-1, 0, 1, 0};
        int dc[] = {0, 1, 0, -1};

        int r = n-1, c = 0;
        int dir = 0; // start going up
        int steps = n;
        int segment = 0;

        while (steps > 0) {
            for (int i = 0; i < steps; i++) {
                grid[r][c] = '#';
                r += dr[dir];
                c += dc[dir];
            }
            // Back up one (we went one too far)
            r -= dr[dir];
            c -= dc[dir];

            // Turn right
            dir = (dir + 1) % 4;
            segment++;
            steps--;

            // Move to next starting position
            r += dr[dir];
            c += dc[dir];
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j > 0) cout << ' ';
                cout << grid[i][j];
            }
            cout << '\n';
        }
        cout << '\n';
    }
    return 0;
}

