int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<string> grid(n, string(n, ' '));

    int top = 0, bottom = n - 1, left = 0, right = n - 1;

    while (left <= right && top <= bottom) {
        // left side: bottom -> top
        for (int i = bottom; i >= top; --i) grid[i][left] = '#';
        ++left;
        if (left > right) break;

        // top side: left -> right
        for (int j = left; j <= right; ++j) grid[top][j] = '#';
        ++top;
        if (top > bottom) break;

        // right side: top -> bottom
        for (int i = top; i <= bottom; ++i) grid[i][right] = '#';
        --right;
        if (left > right) break;

        // bottom side: right -> left
        for (int j = right; j >= left; --j) grid[bottom][j] = '#';
        bottom -= 2; // leave one-space gap between spiral lines
        right -= 1;
        top += 1;
        left += 1;
    }

    for (int i = 0; i < n; ++i) {
        cout << grid[i] << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class GuruguruMoyo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.close();

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = ' ';
            }
        }

        int row = n - 1, col = 0;
        int left = 0, right = n - 1, top = 0, bottom = n - 1;
        int dir = 0; // 0: up, 1: right, 2: down, 3: left

        while (left <= right && top <= bottom) {
            grid[row][col] = '#';
            if (dir == 0) { // moving up
                if (row - 1 < top) {
                    dir = 1;
                    left++;
                    col++;
                } else {
                    row--;
                }
            } else if (dir == 1) { // moving right
                if (col + 1 > right) {
                    dir = 2;
                    top++;
                    row++;
                } else {
                    col++;
                }
            } else if (dir == 2) { // moving down
                if (row + 1 > bottom) {
                    dir = 3;
                    right--;
                    col--;
                } else {
                    row++;
                }
            } else if (dir == 3) { // moving left
                if (col - 1 < left) {
                    dir = 0;
                    bottom--;
                    row--;
                } else {
                    col--;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(grid[i][j]);
                if (j < n - 1) System.out.print(' ');
            }
            System.out.println();
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            char[][] grid = new char[n][n];
            for (char[] row : grid) Arrays.fill(row, ' ');

            for (int k = 0; k < (n + 1) / 2; k++) {
                int left = k, right = n - 1 - k, top = k, bottom = n - 1 - k;
                // Up left side: col=left, rows from bottom to top
                for (int r = bottom; r >= top; r--) grid[r][left] = '#';
                // Right across top: row=top, cols from left to right
                for (int c = left; c <= right; c++) grid[top][c] = '#';
                // Down right side: col=right, rows from top to bottom
                for (int r = top; r <= bottom; r++) grid[r][right] = '#';
                // Left across bottom (partial): row=bottom, cols from right to left+1
                for (int c = right; c >= left + 1; c--) grid[bottom][c] = '#';
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (j > 0) sb.append(' ');
                    sb.append(grid[i][j]);
                }
                sb.append('\n');
            }
            System.out.print(sb);
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        char[][] a = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) a[i][j] = ' ';
        }

        int top = 0, bottom = n - 1, left = 0, right = n - 1;

        while (left <= right && top <= bottom) {
            // bottom row: left -> right
            for (int j = left; j <= right; j++) a[bottom][j] = '#';
            bottom -= 2;
            if (top > bottom || left > right) break;

            // right column: bottom+2 up to top
            for (int i = bottom + 2; i >= top; i--) a[i][right] = '#';
            right -= 2;
            if (top > bottom || left > right) break;

            // top row: right+2 down to left
            for (int j = right + 2; j >= left; j--) a[top][j] = '#';
            top += 2;
            if (top > bottom || left > right) break;

            // left column: top-2 down to bottom
            for (int i = top - 2; i <= bottom; i++) a[i][left] = '#';
            left += 2;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(a[i]);
            if (i + 1 < n) sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}
